func TestNewJSONLogger_CloudLoggingFormatAndTrace(t *testing.T) {
	// Arrange
	t.Setenv("GCP_PROJECT_ID", "ceibuenvivir")
	var buf bytes.Buffer
	base := NewJSONLogger(&buf, "auth", "testing")
	ctx := WithCorrelationID(context.Background(), "corr-123")
	ctx = WithTraceID(ctx, ParseCloudTraceHeader("105445aa7843bc8bf206b12000100000/1;o=1"))

	// Act
	LoggerFromContext(ctx, base).Warn("test warning", slog.Int("code", 400))

	// Assert
	var entry map[string]any
	if err := json.Unmarshal(buf.Bytes(), &entry); err != nil {
		t.Fatalf("expected valid JSON log line, got error: %v", err)
	}
	if entry["severity"] != "WARNING" {
		t.Fatalf("expected severity WARNING, got %v", entry["severity"])
	}
	if entry["message"] != "test warning" {
		t.Fatalf("expected message 'test warning', got %v", entry["message"])
	}
	if entry["service"] != "auth" || entry["env"] != "testing" {
		t.Fatalf("unexpected service/env fields: %v", entry)
	}
	if entry["correlation_id"] != "corr-123" {
		t.Fatalf("expected correlation_id corr-123, got %v", entry["correlation_id"])
	}
	wantTrace := "projects/ceibuenvivir/traces/105445aa7843bc8bf206b12000100000"
	if entry["logging.googleapis.com/trace"] != wantTrace {
		t.Fatalf("expected trace %q, got %v", wantTrace, entry["logging.googleapis.com/trace"])
	}
}

