func TestHTTPMiddleware_RecordsMetricsAndPropagatesHeaders(t *testing.T) {
	// Arrange
	var logBuf bytes.Buffer
	prev := slog.Default()
	slog.SetDefault(NewJSONLogger(&logBuf, "education", "testing"))
	defer slog.SetDefault(prev)

	reg := NewRegistry("education")
	mw := HTTPMiddleware(reg, func(r *http.Request) string {
		if strings.HasPrefix(r.URL.Path, "/api/cursos/") {
			return "/api/cursos/{id}"
		}
		return ""
	})
	handler := mw(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if CorrelationIDFrom(r.Context()) == "" {
			t.Error("expected correlation ID in context")
		}
		if r.URL.Path == "/fail" {
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = w.Write([]byte("boom"))
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	}))

	// Act
	recOK := httptest.NewRecorder()
	reqOK := httptest.NewRequest(http.MethodGet, "/api/cursos/abc-123", nil)
	handler.ServeHTTP(recOK, reqOK)

	recHealth := httptest.NewRecorder()
	handler.ServeHTTP(recHealth, httptest.NewRequest(http.MethodGet, "/health", nil))

	recErr := httptest.NewRecorder()
	handler.ServeHTTP(recErr, httptest.NewRequest(http.MethodPost, "/fail", nil))

	// Assert
	if recOK.Header().Get(HeaderCorrelationID) == "" {
		t.Fatal("expected X-Correlation-ID header in response")
	}
	var metricsOut bytes.Buffer
	_ = reg.WritePrometheus(&metricsOut)
	out := metricsOut.String()
	if !strings.Contains(out, `route="/api/cursos/{id}",status_class="2xx"} 1`) {
		t.Fatalf("expected normalized route metric, got:\n%s", out)
	}
	if !strings.Contains(out, `route="unmatched",status_class="5xx"} 1`) {
		t.Fatalf("expected unmatched fallback route metric for /fail, got:\n%s", out)
	}
	logs := logBuf.String()
	if strings.Contains(logs, `"/health"`) {
		t.Fatalf("expected /health 200 to be omitted from logs, got:\n%s", logs)
	}
	if !strings.Contains(logs, `"severity":"ERROR"`) {
		t.Fatalf("expected 500 request to log at ERROR severity, got:\n%s", logs)
	}
}

