func TestListenAndServeGraceful_CancelsCleanly(t *testing.T) {
	// Arrange
	ctx, cancel := context.WithCancel(context.Background())
	srv := &http.Server{
		Addr:              "127.0.0.1:0",
		ReadHeaderTimeout: time.Second,
		Handler:           http.NewServeMux(),
	}
	called := false

	// Act
	cancel()
	err := ListenAndServeGraceful(ctx, srv, func(context.Context) {
		called = true
	})

	// Assert
	if err != nil {
		t.Fatalf("expected nil error on clean cancel, got %v", err)
	}
	if !called {
		t.Fatal("expected shutdown callback to run")
	}
}
